/**
 * MiniMaxLLMConfiguration
 */
export type MiniMaxLlmConfiguration = {
    /**
     * Provider
     */
    provider?: 'minimax';
    /**
     * Api Key
     */
    api_key: string | Array<string>;
    /**
     * Use Platform Key
     *
     * Run this section on Decibyl's own key for the chosen provider, rather than the account's.
     */
    use_platform_key?: boolean;
    /**
     * Model
     *
     * MiniMax chat model.
     */
    model?: string;
    /**
     * Temperature
     *
     * Sampling temperature. MiniMax requires > 0.
     */
    temperature?: number;
    /**
     * Max Tokens
     *
     * Ceiling on the reply length for one turn. On a phone call this is a latency control as much as a cost one -- without streaming the caller waits for the whole reply to generate. Too low truncates mid-sentence, which sounds like the agent hung up.
     */
    max_tokens?: number | null;
    /**
     * Reasoning Effort
     *
     * How long a reasoning model may think before answering. Only models that accept it are sent it. Thinking time is dead air on a phone call, but too little of it and the model answers in words where it should have called a tool -- which, in a workflow, means never moving off the first step. One of: minimal, low, medium, high.
     */
    reasoning_effort?: string | null;
    /**
     * Base Url
     *
     * MiniMax OpenAI-compatible API endpoint.
     */
    base_url?: string;
};

/**
 * MiniMaxTTSConfiguration
 */
export type MiniMaxTtsConfiguration = {
    /**
     * Provider
     */
    provider?: 'minimax';
    /**
     * Api Key
     */
    api_key: string | Array<string>;
    /**
     * Use Platform Key
     *
     * Run this section on Decibyl's own key for the chosen provider, rather than the account's.
     */
    use_platform_key?: boolean;
    /**
     * Model
     *
     * MiniMax TTS model.
     */
    model?: string;
    /**
     * Voice
     *
     * MiniMax voice ID.
     */
    voice?: string;
    /**
     * Base Url
     *
     * MiniMax TTS API endpoint (must include the /v1/t2a_v2 path). Defaults to the global endpoint; override with https://api.minimaxi.chat/v1/t2a_v2 (mainland China) or https://api-uw.minimax.io/v1/t2a_v2 (US-West).
     */
    base_url?: string;
    /**
     * Speed
     *
     * Speech speed (0.5 to 2.0).
     */
    speed?: number;
    /**
     * Language
     *
     * Language code for synthesis, e.g. 'ta' for Tamil. Sent to MiniMax as language_boost. Leave empty to let MiniMax infer it from the text.
     */
    language?: string | null;
    /**
     * Group Id
     *
     * MiniMax Group ID (found in your MiniMax dashboard under Account → Group).
     */
    group_id: string;
};

